<div class="page-actions"><div><h2>Online Payment Transactions</h2><p>Monitor non-sensitive gateway transaction data, payment verification status, receipts and recent online donations.</p></div><div class="page-action-stack"><a class="outline-link" href="<?=url('admin/online-payments/export')?>">↓ Export CSV</a><a class="admin-btn" href="<?=url('admin/developer/payment-gateway')?>">Payment Gateway Settings</a></div></div>
<div class="online-payment-stats"><article><span>◆</span><div><small>Total Transactions</small><b><?=number_format((int)($stats['total']??0))?></b></div></article><article><span>✓</span><div><small>Successful Amount</small><b><?=money((float)($stats['successful_amount']??0))?></b></div></article><article><span>◷</span><div><small>Pending / Processing</small><b><?=number_format((int)($stats['pending']??0))?></b></div></article><article><span>×</span><div><small>Failed Payments</small><b><?=number_format((int)($stats['failed']??0))?></b></div></article><article><span>☀</span><div><small>Today's Donations</small><b><?=money((float)($stats['today_amount']??0))?></b></div></article></div>
<section class="admin-panel online-payment-table-panel"><form method="get" action="<?=url('admin/online-payments')?>" class="payment-filter-bar"><input name="q" value="<?=e($q??'')?>" placeholder="Reference, transaction ID, donor, email…"><select name="status"><option value="">All statuses</option><?php foreach(['pending','processing','successful','failed','cancelled','refunded'] as $st):?><option value="<?=$st?>" <?=($status??'')===$st?'selected':''?>><?=e(ucfirst($st))?></option><?php endforeach;?></select><select name="gateway"><option value="">All gateways</option><option value="payhere" <?=($gateway??'')==='payhere'?'selected':''?>>PayHere</option></select><input type="date" name="from" value="<?=e($from??'')?>" title="From date"><input type="date" name="to" value="<?=e($to??'')?>" title="To date"><input type="number" name="min" min="0" step="0.01" value="<?=e((string)($min??''))?>" placeholder="Min LKR"><input type="number" name="max" min="0" step="0.01" value="<?=e((string)($max??''))?>" placeholder="Max LKR"><button class="outline-link">Filter</button><a class="outline-link" href="<?=url('admin/online-payments')?>">Clear</a></form><div class="table-wrap"><table class="online-payments-table"><thead><tr><th>Reference</th><th>Donor</th><th>Amount</th><th>Gateway</th><th>Status</th><th>Paid / Created</th><th>Action</th></tr></thead><tbody><?php foreach($transactions as $tx):?><tr><td><b><?=e($tx['public_id'])?></b><small><?=e($tx['gateway_order_id'])?></small><?php if($tx['receipt_number']):?><small>Receipt: <?=e($tx['receipt_number'])?></small><?php endif;?></td><td><b><?=e($tx['donor_name'])?></b><small><?=e($tx['donor_email']?:'No email')?></small><small><?=e($tx['donor_phone'])?></small></td><td><b><?=money($tx['amount'])?></b><small><?=e($tx['campaign_title']?:'General Fund')?></small></td><td><b><?=e(ucfirst($tx['gateway']))?></b><small><?=e($tx['payment_method']?:'Gateway checkout')?></small></td><td><span class="payment-status-pill <?=e($tx['status'])?>"><?=e(ucfirst($tx['status']))?></span></td><td><b><?=e($tx['paid_at']?date('d M Y · h:i A',strtotime($tx['paid_at'])):date('d M Y · h:i A',strtotime($tx['created_at'])))?></b><small><?=e($tx['paid_at']?'Paid':'Created')?></small></td><td><a class="outline-link mini" href="<?=url('admin/online-payments/view/'.$tx['id'])?>">View Details →</a></td></tr><?php endforeach;?><?php if(!$transactions):?><tr><td colspan="7"><div class="empty-card">No online payment transactions match the selected filters.</div></td></tr><?php endif;?></tbody></table></div><?=admin_pagination($pagination??[])?></section>
